// VCA-VOL vragenbank — [modId, vraag, [juist, fout, fout(, fout)], uitleg]
window.VCA_VRAGEN = [

  // ───────── Wetgeving & verantwoordelijkheden ─────────
  ["wet", "Wie is volgens de Arbowet eindverantwoordelijk voor veilig en gezond werken in het bedrijf?", ["De werkgever", "De preventiemedewerker", "De Nederlandse Arbeidsinspectie"], "De werkgever is eindverantwoordelijk. Werknemers hebben wel eigen plichten, zoals gevaren melden."],
  ["wet", "Welke regelgeving bevat de algemene kaderbepalingen, die verder worden uitgewerkt in het Arbobesluit en de Arboregeling?", ["De Arbowet", "De Arbocatalogus van de branche", "Het Burgerlijk Wetboek"], "De Arbowet is de kaderwet met doelvoorschriften. Het Arbobesluit werkt die uit en de Arboregeling bevat de meest gedetailleerde voorschriften."],
  ["wet", "Wat is een Arbocatalogus?", ["Afspraken tussen werkgevers en werknemers in een branche over hoe zij aan de doelvoorschriften van de Arbowet voldoen", "Een lijst van bedrijven die door de Arbeidsinspectie zijn beboet", "Een catalogus met goedgekeurde PBM’s"], "De Arbowet schrijft doelen voor; in de Arbocatalogus leggen werkgevers en werknemers vast met welke middelen en methoden zij die doelen halen."],
  ["wet", "Welke van deze verplichtingen heeft een werknemer volgens de Arbowet?", ["Gevaren die hij opmerkt melden", "Zelf een RI&E opstellen voor zijn werkplek", "Zelf zijn persoonlijke beschermingsmiddelen aanschaffen en betalen"], "Werknemers moeten onder meer gevaren melden, PBM’s juist gebruiken en veiligheidsvoorzieningen niet uitschakelen. De RI&E en PBM’s zijn de verantwoordelijkheid van de werkgever."],
  ["wet", "Een werknemer ziet een situatie waarin ernstig gevaar voor personen onmiddellijk dreigt. Wat mag hij volgens de Arbowet doen?", ["Het werk onderbreken en dit zo snel mogelijk melden aan zijn leidinggevende", "Alleen doorwerken tot hij de situatie schriftelijk heeft gemeld", "Pas stoppen als de Arbeidsinspectie is ingeschakeld"], "De Arbowet geeft de werknemer het recht het werk te onderbreken bij ernstig en direct gevaar. Hij meldt dit zo snel mogelijk en mag daarvoor niet worden benadeeld."],
  ["wet", "Welk arbeidsongeval moet de werkgever direct melden bij de Nederlandse Arbeidsinspectie?", ["Een ongeval met dodelijke afloop, blijvend letsel of ziekenhuisopname", "Elk ongeval waarbij de EHBO-trommel is gebruikt", "Alleen ongevallen met materiële schade boven € 10.000"], "Ernstige arbeidsongevallen (dood, blijvend letsel of ziekenhuisopname) moet de werkgever direct melden. Andere ongevallen registreert hij zelf."],
  ["wet", "Wat mag de Nederlandse Arbeidsinspectie doen als een inspecteur ernstig gevaar voor personen vaststelt?", ["Het werk stilleggen", "Alleen een schriftelijk advies aan de ondernemingsraad sturen", "Het VCA-certificaat van het bedrijf intrekken"], "De Arbeidsinspectie kan werk stilleggen en boetes opleggen. Het VCA-certificaat wordt verstrekt en ingetrokken door de certificerende instelling, niet door de inspectie."],
  ["wet", "Wat is een taak van de preventiemedewerker?", ["Meewerken aan het opstellen en uitvoeren van de RI&E", "Zieke werknemers begeleiden bij hun re-integratie", "Elektrische installaties keuren volgens NEN 3140"], "De preventiemedewerker werkt mee aan de RI&E, voert maatregelen uit en adviseert en werkt samen met de OR. Verzuimbegeleiding is een taak van de bedrijfsarts."],
  ["wet", "Tot hoeveel werknemers mag de werkgever de taken van preventiemedewerker zelf uitvoeren?", ["25", "50", "10"], "In bedrijven met maximaal 25 werknemers mag de werkgever zelf preventiemedewerker zijn. Daarboven moet hij een of meer werknemers aanwijzen."],
  ["wet", "Welke taak hoort bij de bedrijfshulpverlening (BHV)?", ["Alarmeren en evacueren van werknemers en andere aanwezigen", "De RI&E beoordelen en goedkeuren", "Ernstige ongevallen melden bij de Arbeidsinspectie"], "BHV-taken zijn: eerste hulp verlenen, beginnende brand en ongevallen beperken en bestrijden, en alarmeren en evacueren."],
  ["wet", "Welk recht heeft de ondernemingsraad (OR) bij regelingen op het gebied van arbeidsomstandigheden?", ["Instemmingsrecht", "Uitsluitend informatierecht", "Het recht om zelf de RI&E te laten toetsen en goed te keuren"], "Voor regelingen over arbeidsomstandigheden heeft de werkgever de instemming van de OR nodig (artikel 27 WOR)."],
  ["wet", "Wat is een taak van de bedrijfsarts?", ["Zieke werknemers begeleiden en arbeidsgezondheidskundig onderzoek (PAGO/PMO) uitvoeren", "Werkvergunningen afgeven voor risicovol werk", "TRA’s opstellen voor gevaarlijke klussen"], "De bedrijfsarts begeleidt verzuim en onderzoekt de gezondheid in relatie tot het werk. Vergunningen en TRA’s horen bij de uitvoering en organisatie van het werk."],
  ["wet", "Mag een werknemer zelf de bedrijfsarts raadplegen over zijn gezondheid in relatie tot het werk?", ["Ja, iedere werknemer heeft toegang tot de bedrijfsarts, ook zonder ziekmelding", "Nee, alleen via zijn leidinggevende", "Alleen als hij langer dan zes weken ziek is"], "De Arbowet regelt dat werknemers de bedrijfsarts vrij kunnen raadplegen (open spreekuur), ook als ze niet ziek zijn."],
  ["wet", "Welke verplichting heeft de werkgever tegenover nieuwe werknemers?", ["Doeltreffende voorlichting en onderricht geven over de risico’s en maatregelen", "Alleen een VCA-diploma eisen", "Ze de eerste maand uitsluitend kantoorwerk laten doen"], "De werkgever moet alle werknemers, en zeker nieuwe, goed voorlichten over de risico’s van hun werk en de maatregelen daartegen."],
  ["wet", "Een vat met olie lekt en de plas stroomt richting een straatkolk. Wat doe je, als het veilig kan?", ["Verspreiding tegenhouden met absorptiemateriaal of een afdekmat en het incident melden", "De plas met water wegspoelen naar het riool", "Het vat laten staan tot de milieudienst langskomt"], "Voorkom dat de olie in bodem of riool komt en meld het milieu-incident, zodat het goed kan worden opgeruimd."],
  ["wet", "Waarom moet gevaarlijk afval, zoals verfresten en oliehoudende poetslappen, gescheiden worden ingezameld?", ["Omdat het schadelijk is voor het milieu en apart verwerkt moet worden", "Omdat het dan goedkoper samen met het restafval kan worden afgevoerd", "Omdat het anders te snel vergaat in de container"], "Gevaarlijk afval kan bodem, water en lucht vervuilen. Het moet daarom gescheiden worden ingezameld en door een erkende verwerker worden afgevoerd."],

  // ───────── Risico’s & ongevallen ─────────
  ["risico", "Wat is het verschil tussen gevaar en risico?", ["Gevaar kan schade veroorzaken; risico is de kans dat die schade optreedt, gecombineerd met de ernst ervan", "Er is geen verschil, het zijn twee woorden voor hetzelfde", "Risico kan schade veroorzaken; gevaar is de kans dat het misgaat"], "Een gevaar is een bron van mogelijke schade. Het risico drukt uit hoe groot de kans is dat het misgaat en hoe ernstig de gevolgen dan zijn."],
  ["risico", "Hoe wordt een risico berekend?", ["Risico = kans × effect", "Risico = kans + blootstellingstijd", "Risico = effect ÷ kans"], "Het risico is het product van de kans dat iets gebeurt en het effect (de ernst van de gevolgen)."],
  ["risico", "Welke omschrijving is een risico en niet alleen een gevaar?", ["De kans dat een voorbijganger in de onafgezette bouwput valt en daarbij ernstig letsel oploopt", "De onafgezette bouwput", "De diepte van de bouwput"], "De bouwput zelf is het gevaar. Het risico beschrijft de kans dat het misgaat én de ernst van de gevolgen."],
  ["risico", "Welk bedrijf moet een risico-inventarisatie en -evaluatie (RI&E) hebben?", ["Elk bedrijf met personeel in dienst", "Alleen bedrijven met meer dan 25 werknemers", "Alleen bedrijven die met gevaarlijke stoffen werken"], "Iedere werkgever met personeel is verplicht een RI&E op te stellen, ongeacht de omvang of de branche."],
  ["risico", "Wat hoort verplicht bij de RI&E?", ["Een plan van aanpak met maatregelen, termijnen en verantwoordelijken", "Een lijst met werknemers die een ongeval hebben veroorzaakt", "Een begroting van de verwachte schadekosten per jaar"], "In het plan van aanpak staat welke maatregelen worden genomen, wie daarvoor verantwoordelijk is en wanneer ze klaar moeten zijn."],
  ["risico", "Wanneer moet de RI&E worden aangepast?", ["Als de werkomstandigheden of werkmethoden veranderen, of ervaringen daartoe aanleiding geven", "Alleen als de Arbeidsinspectie erom vraagt", "Uitsluitend eens per tien jaar"], "De RI&E moet actueel zijn. Nieuwe machines, werkwijzen, stoffen of ongevallen zijn aanleiding om haar bij te werken."],
  ["risico", "Wat is de juiste volgorde van de arbeidshygiënische strategie?", ["Bronaanpak – collectieve maatregelen – individuele maatregelen – PBM", "PBM – individuele maatregelen – collectieve maatregelen – bronaanpak", "Collectieve maatregelen – bronaanpak – PBM – individuele maatregelen"], "Eerst het gevaar bij de bron wegnemen, dan collectief afschermen, dan individuele maatregelen en pas als laatste PBM."],
  ["risico", "Een oplosmiddelhoudende verf wordt vervangen door een verf op waterbasis. Welke stap van de arbeidshygiënische strategie is dit?", ["Bronaanpak", "Collectieve maatregel", "Individuele maatregel", "Persoonlijke bescherming"], "Door een minder schadelijk product te gebruiken, neem je het gevaar bij de bron weg. Dat is de meest effectieve stap."],
  ["risico", "Langs een dakrand wordt een vaste leuning geplaatst. Welke stap van de arbeidshygiënische strategie is dit?", ["Collectieve maatregel", "Bronaanpak", "Persoonlijke bescherming"], "Een leuning beschermt iedereen op het dak tegelijk tegen vallen. Het gevaar (de hoogte) blijft, dus het is geen bronaanpak."],
  ["risico", "Volgens de ongevallenpiramide van Bird staan tegenover 1 ernstig ongeval ongeveer hoeveel bijna-ongevallen?", ["600", "30", "10"], "De piramide van Bird: 1 ernstig ongeval, 10 ongevallen met licht letsel, 30 ongevallen met alleen schade en 600 bijna-ongevallen."],
  ["risico", "Waar staat het getal 30 voor in de piramide van Bird?", ["Ongevallen met alleen materiële schade", "Ongevallen met licht letsel", "Bijna-ongevallen"], "Bird: 1 ernstig ongeval, 10 met licht letsel, 30 met alleen schade, 600 bijna-ongevallen."],
  ["risico", "Wat is de belangrijkste les van de piramide van Bird?", ["Door bijna-ongevallen te melden en de oorzaken aan te pakken, verklein je de kans op ernstige ongevallen", "Ernstige ongevallen zijn toeval en niet te voorkomen", "Alleen ongevallen met letsel zijn het onderzoeken waard"], "Ernstige ongevallen en bijna-ongevallen hebben vaak dezelfde oorzaken. Wie de brede basis aanpakt, verkleint ook de top."],
  ["risico", "Wat is een bijna-ongeval?", ["Een onbedoelde gebeurtenis die tot letsel of schade had kunnen leiden, maar waarbij dat net niet gebeurde", "Een ongeval met alleen licht letsel", "Een ongeval waarbij alleen materiële schade ontstond"], "Bij een bijna-ongeval is er (nog) geen letsel of schade. Het is een waarschuwing dat het de volgende keer wel mis kan gaan."],
  ["risico", "Een collega struikelt over een slang, maar kan zich vastgrijpen en raakt niet gewond. Wat doe je?", ["Het melden als bijna-ongeval en de slang laten verleggen", "Niets, er is immers niemand gewond geraakt", "Alleen de collega vragen voortaan beter op te letten"], "Bijna-ongevallen moet je melden, zodat de oorzaak wordt weggenomen voordat er wél iemand gewond raakt."],
  ["risico", "Wat is volgens onderzoek bij de meeste ongevallen een directe oorzaak?", ["Onveilig gedrag (onveilige handelingen)", "Defecte machines", "Extreme weersomstandigheden"], "Bij de meeste ongevallen speelt menselijk gedrag een rol. Achter dat gedrag zitten vaak basisoorzaken zoals tijdsdruk of gebrekkige instructie."],
  ["risico", "Welke van deze is een onveilige situatie (en geen onveilige handeling)?", ["Een vloeropening zonder afzetting of afdekking", "Een werknemer die zonder helm onder een steiger doorloopt", "Een collega die de beschermkap van een slijpmachine haalt"], "Een onveilige situatie is een toestand van de werkplek. De andere twee zijn handelingen: iemand doet iets onveiligs."],
  ["risico", "Waarom is het bij ongevalsonderzoek belangrijk ook de basisoorzaken te achterhalen?", ["Alleen door onderliggende oorzaken zoals tijdsdruk of ontbrekende instructie aan te pakken, voorkom je herhaling", "Omdat je dan kunt bepalen wie de schade moet betalen", "Omdat de verzekeraar anders niet uitkeert"], "Directe oorzaken zijn vaak symptomen. Als de basisoorzaak blijft bestaan, gebeurt een vergelijkbaar ongeval opnieuw."],
  ["risico", "Wat kenmerkt een goede veiligheidscultuur?", ["Medewerkers spreken elkaar aan op onveilig gedrag en melden incidenten zonder angst voor straf", "Veiligheid wordt vooral besproken na een ernstig ongeval", "Veiligheid is de taak van de veiligheidskundige, niet van de uitvoering"], "In een goede veiligheidscultuur voelt iedereen zich verantwoordelijk en is melden en aanspreken normaal."],

  // ───────── Operationeel leidinggevende ─────────
  ["vol", "Waarom is het belangrijk dat jij als operationeel leidinggevende zelf altijd de veiligheidsregels naleeft?", ["Je hebt een voorbeeldfunctie: medewerkers nemen jouw gedrag over", "Omdat jij als enige aansprakelijk bent bij een ongeval", "Omdat het VCA-VOL-diploma anders vervalt"], "Medewerkers kijken naar hun leidinggevende. Wie zelf regels overtreedt, kan anderen er niet geloofwaardig op aanspreken."],
  ["vol", "Je ziet een medewerker op een dakrand werken zonder de voorgeschreven valbeveiliging. Wat doe je?", ["Het werk direct laten stoppen en pas verder laten gaan als het veilig is", "Er na afloop van de dienst iets van zeggen", "Het noteren als onderwerp voor de volgende toolboxmeeting"], "Bij direct gevaar grijp je meteen in. Later bespreken is te laat als er ondertussen iemand valt."],
  ["vol", "Hoe spreek je een medewerker het beste aan op onveilig gedrag?", ["Direct, rustig en gericht op het gedrag, met uitleg waarom het onveilig is", "Later, via een e-mail aan de hele ploeg, zodat niemand zich persoonlijk aangesproken voelt", "Tijdens de pauze waar iedereen bij is, zodat anderen er ook van leren"], "Spreek iemand direct aan op het gedrag, niet op de persoon, en leg uit waarom. Zo begrijpt hij het en neemt hij het eerder aan."],
  ["vol", "Tijdens een werkplekinspectie zie je dat een ploeg alles volgens de regels doet. Wat doe je?", ["Ze daar een compliment voor geven", "Niets zeggen, want veilig werken is gewoon normaal", "Toch iets zoeken om op aan te merken, zodat ze scherp blijven"], "Positieve feedback op veilig gedrag versterkt dat gedrag. Het werkt beter en blijvender dan alleen corrigeren."],
  ["vol", "Wat is een toolboxmeeting?", ["Een korte bijeenkomst over een veiligheidsonderwerp", "Een jaarlijkse vergadering van directie en ondernemingsraad over het arbobeleid", "Een cursus over het onderhouden van gereedschap"], "Een toolboxmeeting is een korte, praktische bijeenkomst met de ploeg over een actueel veiligheidsonderwerp."],
  ["vol", "Hoe maak je een toolboxmeeting het meest effectief?", ["Een onderwerp kiezen dat past bij het werk van dat moment en de medewerkers actief laten meepraten", "Een hoofdstuk uit het veiligheidshandboek voorlezen", "Zo veel mogelijk onderwerpen in één keer behandelen"], "Een actueel onderwerp en interactie zorgen dat medewerkers de boodschap herkennen, onthouden en toepassen."],
  ["vol", "Wat is het doel van een werkplekinspectie door de leidinggevende?", ["Onveilige situaties en handelingen opsporen, zodat ze kunnen worden verbeterd", "Vaststellen welke medewerker een waarschuwing moet krijgen", "Controleren of de planning wordt gehaald"], "Een werkplekinspectie is gericht op verbeteren: gevaren tijdig signaleren en wegnemen, en goed gedrag bevestigen."],
  ["vol", "Wat is de juiste volgorde bij het geven van een werkinstructie?", ["Vertellen – tonen – laten doen – controleren", "Tonen – controleren – vertellen – laten doen", "Laten doen – vertellen – controleren – tonen"], "Eerst uitleggen, dan voordoen, dan de medewerker het zelf laten doen en tot slot controleren of het goed gaat."],
  ["vol", "Een nieuwe medewerker spreekt nauwelijks Nederlands. Hoe zorg je dat hij de veiligheidsinstructie begrijpt?", ["Instructie geven in een taal die hij begrijpt, voordoen en controleren of hij het begrepen heeft", "Hem het Nederlandstalige veiligheidshandboek laten ondertekenen", "Ervan uitgaan dat hij het werk van collega’s afkijkt"], "Voorlichting moet doeltreffend zijn. Een handtekening zegt niets; controleer of de instructie echt is begrepen."],
  ["vol", "Waarom lopen nieuwe medewerkers een verhoogd risico op ongevallen?", ["Ze kennen de werkplek, de gevaren en de werkwijzen nog onvoldoende", "Ze zijn in de eerste maanden minder goed verzekerd", "Ze krijgen pas na hun proeftijd PBM’s"], "Nieuwe medewerkers missen ervaring met de specifieke gevaren. Extra instructie en begeleiding zijn daarom nodig."],
  ["vol", "Een 16-jarige vakantiekracht komt in jouw ploeg werken. Wat geldt voor jou als leidinggevende?", ["Je zorgt voor extra voorlichting en deskundig toezicht en laat hem geen werk doen dat voor jongeren verboden is", "Hij mag alle werkzaamheden doen zolang hij een VCA-diploma heeft", "Omdat hij er maar kort is, hoeft hij geen instructie te krijgen"], "Voor jongeren onder de 18 gelden extra beschermende regels: sommige werkzaamheden zijn verboden en toezicht is vereist."],
  ["vol", "Wie is verantwoordelijk voor de arbeidsomstandigheden van een uitzendkracht die op jouw project werkt?", ["Het inlenende bedrijf, waar hij het werk doet", "Het uitzendbureau", "De uitzendkracht zelf"], "Voor de Arbowet is de inlener de werkgever. Hij zorgt voor veilige omstandigheden, instructie en PBM’s op de werkplek."],
  ["vol", "Een onderaannemer begint morgen op jouw project. Wat regel je vooraf?", ["Je informeert hem over de specifieke risico’s, regels en noodprocedures van het project", "Niets, een onderaannemer is voor alles zelf verantwoordelijk", "Je controleert alleen of hij zijn eigen gereedschap meeneemt"], "De onderaannemer is verantwoordelijk voor zijn eigen personeel, maar moet wel weten welke risico’s en afspraken op jouw project gelden."],
  ["vol", "Wat is het doel van ongevalsonderzoek?", ["De oorzaken achterhalen om herhaling te voorkomen", "De schuldige vinden, zodat die kan worden gestraft", "Bewijs verzamelen voor de verzekeraar"], "Ongevalsonderzoek is gericht op leren en voorkomen. Zoeken naar een schuldige zorgt er juist voor dat mensen minder melden."],
  ["vol", "Na een ernstig ongeval zijn het slachtoffer verzorgd en het gevaar weggenomen. Wat doe je met de plaats van het ongeval?", ["Zo veel mogelijk ongewijzigd laten voor het onderzoek", "Direct opruimen zodat het werk verder kan", "De betrokken machine meteen laten repareren"], "Sporen zijn nodig om de oorzaak vast te stellen. Bij een meldingsplichtig ongeval komt de Arbeidsinspectie ter plaatse onderzoek doen."],
  ["vol", "Wie stelt een taakrisicoanalyse (TRA) bij voorkeur op?", ["De leidinggevende samen met de medewerkers die het werk gaan uitvoeren", "De directeur alleen, op kantoor", "Een externe adviseur, zonder overleg met de uitvoering"], "De uitvoerenden kennen het werk en de praktische gevaren het best. Door hen te betrekken wordt de TRA vollediger en beter nageleefd."],
  ["vol", "Bij een ploegwissel wordt een half afgemaakte klus overgedragen. Wat is het belangrijkste?", ["Een duidelijke overdracht van de stand van het werk, de risico’s en de genomen maatregelen", "Dat de nieuwe ploeg zelf uitzoekt hoe het ervoor staat", "Dat de werkvergunning ongezien in de keet blijft liggen"], "Bij overdrachten gaat vaak informatie verloren. Een goede overdracht voorkomt dat de volgende ploeg onbewust in gevaar komt."],
  ["vol", "Een medewerker meldt jou een gevaarlijke situatie. Hoe reageer je?", ["Hem bedanken, de situatie beoordelen, maatregelen nemen en terugkoppelen wat ermee is gedaan", "Zeggen dat hij zich op zijn eigen werk moet richten", "De melding noteren en bij de volgende RI&E bekijken"], "Serieus reageren en terugkoppelen stimuleert het melden. Wie nooit iets terughoort, stopt met melden."],
  ["vol", "De opdrachtgever zet druk om sneller te werken, waardoor de afgesproken veiligheidsmaatregelen niet haalbaar zijn. Wat doe je?", ["Het werk niet onveilig laten uitvoeren en het probleem bespreken met je leiding en de opdrachtgever", "De maatregelen deze ene keer weglaten om de planning te halen", "De medewerkers zelf laten kiezen of ze het risico nemen"], "Veiligheid gaat voor planning. Jij bent verantwoordelijk voor veilig werken in je ploeg en moet het probleem escaleren."],
  ["vol", "Welke aanpak zorgt het meest blijvend voor veilig gedrag in je ploeg?", ["Veilig gedrag direct en positief bevestigen", "Alleen straffen als er iets misgaat", "Eén keer per jaar een grote veiligheidscampagne houden"], "Gedrag dat direct positief wordt bevestigd, wordt vaker herhaald. Straf alleen werkt vooral zolang de leidinggevende kijkt."],

  // ───────── Procedures & vergunningen ─────────
  ["procedures", "Wat is een werkvergunning?", ["Een schriftelijke toestemming om risicovol werk uit te voeren onder vastgelegde voorwaarden en maatregelen", "Een vergunning van de gemeente om te mogen bouwen", "Een bewijs dat een medewerker VCA-gecertificeerd is"], "In de werkvergunning staan de gevaren, de te nemen maatregelen en de geldigheid van het werk. Zonder vergunning mag het werk niet beginnen."],
  ["procedures", "Wie geeft een werkvergunning af?", ["De vergunningverlener namens de eigenaar van de installatie", "De medewerker die het werk gaat uitvoeren", "De Nederlandse Arbeidsinspectie"], "De vergunningverlener kent de installatie en weet welke gevaren er zijn en welke maatregelen nodig zijn."],
  ["procedures", "Tijdens het werk blijkt er een leiding te lopen die niet op de werkvergunning staat. Wat doe je?", ["Het werk stoppen en contact opnemen met de vergunningverlener", "Doorwerken en het achteraf op de vergunning noteren", "De leiding zelf afsluiten en verder gaan"], "Als de situatie afwijkt van de vergunning, klopt de risicobeoordeling niet meer. Stop en laat de vergunning opnieuw beoordelen."],
  ["procedures", "Tijdens je werk gaat het algemene alarm af. Na afloop van het alarm wil je verder. Wat geldt voor je werkvergunning?", ["Die is vervallen; je mag pas verder na nieuwe toestemming van de vergunningverlener", "Die blijft gewoon geldig, het werk was al goedgekeurd", "Je mag verder als je het tijdstip van het alarm op de vergunning noteert"], "Een noodsignaal laat de werkvergunning vervallen. De situatie kan veranderd zijn, dus eerst moet opnieuw worden beoordeeld of het veilig is."],
  ["procedures", "Wat doe je aan het einde van de werkzaamheden met de werkvergunning?", ["Afmelden bij de vergunningverlener nadat de werkplek veilig en opgeruimd is achtergelaten", "Weggooien, want het werk is klaar", "Bewaren voor de volgende keer dat hetzelfde werk wordt gedaan"], "Door af te melden weet de installatie-eigenaar dat het werk klaar is en de installatie weer veilig in gebruik kan."],
  ["procedures", "Wanneer stel je een TRA (taakrisicoanalyse) op?", ["Voor risicovolle of niet-routinematige werkzaamheden waarvoor geen standaardprocedure bestaat", "Alleen nadat er een ongeval is gebeurd", "Elke werkdag opnieuw, ook voor kantoorwerk"], "Een TRA is bedoeld voor werk met verhoogd risico of werk dat niet volgens een vaste procedure verloopt."],
  ["procedures", "Hoe is een TRA opgebouwd?", ["Het werk wordt in stappen verdeeld; per stap worden de gevaren en de maatregelen bepaald", "Per medewerker wordt vastgelegd hoeveel ongevallen hij heeft gehad", "Er wordt een lijst gemaakt van de benodigde materialen en gereedschappen"], "Door het werk op te delen in stappen, ontdek je per stap de gevaren en leg je vast welke maatregel daarbij hoort."],
  ["procedures", "Wat is een LMRA (Laatste Minuut Risico Analyse)?", ["Een korte risicobeoordeling door de uitvoerende, vlak voor aanvang op de werkplek", "Een uitgebreide analyse die de directie jaarlijks opstelt", "Een medische controle vlak voor de dienst"], "Met de LMRA controleer je vlak voor het begin of de situatie op de werkplek veilig is en overeenkomt met wat is afgesproken."],
  ["procedures", "Bij je LMRA twijfel je of het werk veilig kan worden uitgevoerd. Wat doe je?", ["Niet beginnen en overleggen met je leidinggevende", "Voorzichtig beginnen en extra goed opletten", "Beginnen, want de werkvergunning is al afgegeven"], "Bij twijfel niet beginnen. De LMRA is juist bedoeld om op dat moment nog ‘stop’ te kunnen zeggen."],
  ["procedures", "Wat houdt LOTO (Lock Out – Tag Out) in?", ["Energiebronnen afschakelen, vergrendelen met een slot en voorzien van een label", "Een machine met een label markeren als ‘nieuw’ of ‘gekeurd’", "Een ruimte afsluiten en de sleutel bij de receptie afgeven"], "Met LOTO voorkom je dat een installatie onverwacht wordt ingeschakeld terwijl er iemand aan werkt."],
  ["procedures", "Drie monteurs werken tegelijk aan dezelfde machine. Hoe wordt de werkschakelaar vergrendeld?", ["Iedere monteur hangt zijn eigen slot aan de vergrendeling", "De eerste monteur hangt een slot en de anderen vertrouwen daarop", "De ploegleider blijft bij de schakelaar staan"], "Pas als de laatste monteur zijn slot verwijdert, kan de machine worden ingeschakeld. Zo is iedereen persoonlijk beschermd."],
  ["procedures", "Welke maatregel hoort bij heet werk, zoals lassen of slijpen, in een omgeving met brandbaar materiaal?", ["Brandbare materialen verwijderen of afdekken en een brandwacht met blusmiddel inzetten", "Het werk ’s avonds doen als er minder mensen zijn", "De omgeving extra verwarmen zodat de materialen droog blijven"], "Vonken en hete deeltjes kunnen ver wegspringen. Brandbaar materiaal moet weg of worden afgedekt en er moet direct geblust kunnen worden."],
  ["procedures", "Waarom blijft de brandwacht na afloop van heet werk nog enige tijd aanwezig?", ["Omdat smeulend materiaal pas later kan gaan branden", "Om het gereedschap op te ruimen", "Om de werkvergunning te laten verlengen"], "Vonken kunnen in kieren en isolatie blijven smeulen. Een brand kan daardoor pas na geruime tijd uitbreken."],
  ["procedures", "Wat moet je doen voordat je mechanisch gaat graven?", ["Een KLIC-melding (graafmelding) doen bij het Kadaster", "Alleen de gemeente telefonisch informeren", "Niets, zolang je minder dan 1 meter diep graaft"], "De graafmelding is verplicht bij mechanisch graven. Je ontvangt dan tekeningen van de kabels en leidingen in het gebied."],
  ["procedures", "Je graaft in de buurt van een kabel die op de KLIC-tekening staat. Hoe bepaal je de exacte ligging?", ["Met de hand een proefsleuf graven", "Met de graafmachine, want de tekening is exact", "Met een grondboor, zodat je de kabel snel vindt"], "De ligging op de KLIC-tekening is indicatief. Met een handmatig gegraven proefsleuf stel je vast waar de kabel echt ligt."],
  ["procedures", "Je raakt tijdens graafwerk een gasleiding en ruikt gas. Wat doe je?", ["Stoppen, ontstekingsbronnen vermijden, het gebied bovenwinds ontruimen en de netbeheerder of 112 bellen", "Het gat snel dichtgooien met zand", "Het lek met tape afdichten en doorwerken"], "Uitstromend gas kan ontbranden of exploderen. Breng mensen in veiligheid en laat de netbeheerder het lek dichten."],
  ["procedures", "Je ziet dat pallets een nooduitgang blokkeren. Wat doe je?", ["Direct laten weghalen", "Het bespreken in de volgende toolboxmeeting", "Een bordje ophangen dat de uitgang tijdelijk geblokkeerd is"], "Nooduitgangen en vluchtwegen moeten altijd vrij zijn. Bij een calamiteit is er geen tijd om ze eerst vrij te maken."],
  ["procedures", "Waarom zijn orde en netheid op de werkplek belangrijk voor de veiligheid?", ["Ze voorkomen struikelen, uitglijden en brand en houden vluchtwegen vrij", "Ze zijn vooral belangrijk voor de uitstraling naar de klant", "Ze zijn alleen wettelijk verplicht in kantoren en kantines"], "Rondslingerend materiaal is een van de meest voorkomende oorzaken van struikel- en valongevallen."],

  // ───────── Noodsituaties ─────────
  ["nood", "Je komt als eerste bij een ongeval. Wat is de juiste volgorde?", ["Eigen veiligheid – alarmeren – eerste hulp verlenen", "Eerste hulp verlenen – alarmeren – eigen veiligheid", "Alarmeren – slachtoffer verplaatsen – eigen veiligheid"], "Word niet zelf het volgende slachtoffer. Zorg eerst dat het voor jou veilig is, alarmeer dan en verleen daarna hulp."],
  ["nood", "Welke informatie geef je bij het alarmeren van hulpdiensten?", ["Wat er is gebeurd, waar, hoeveel slachtoffers er zijn en wie je bent", "Alleen je naam en telefoonnummer", "Alleen de naam van het slachtoffer"], "Met deze informatie kunnen hulpdiensten snel de juiste hulp naar de juiste plek sturen."],
  ["nood", "Wanneer mag je een slachtoffer verplaatsen?", ["Alleen als er direct gevaar is voor het slachtoffer of voor jezelf", "Altijd, zodat hij comfortabel ligt", "Alleen als hij daar zelf om vraagt"], "Verplaatsen kan letsel, bijvoorbeeld aan de wervelkolom, verergeren. Doe het alleen als blijven liggen gevaarlijker is."],
  ["nood", "Het ontruimingssignaal gaat af. Hoe verlaat je het gebouw?", ["Via de trap en de vluchtroute; nooit met de lift", "Met de lift, omdat je dan sneller buiten bent", "Eerst je spullen ophalen en dan via de dichtstbijzijnde uitgang"], "Een lift kan uitvallen of naar een verdieping met brand of rook gaan. Gebruik altijd de trap."],
  ["nood", "Waarom meld je je na een ontruiming op de verzamelplaats?", ["Zodat gecontroleerd kan worden of iedereen buiten is", "Om te horen of je naar huis mag", "Om daar je werkvergunning in te leveren"], "Als iemand ontbreekt, weten de hulpdiensten dat er mogelijk nog iemand in het gebouw is."],
  ["nood", "Wie leidt een ontruiming op het werk?", ["De BHV’ers, volgens het ontruimingsplan", "De medewerker die het dichtst bij de uitgang staat", "De ondernemingsraad"], "BHV’ers zijn opgeleid om te alarmeren en te evacueren en volgen daarbij het ontruimingsplan van het bedrijf."],
  ["nood", "Er komt een giftige gaswolk vrij. In welke richting vlucht je?", ["Dwars op de windrichting", "Met de wind mee", "Tegen de wind in, dwars door de wolk"], "Met de wind mee blijf je in de wolk. Door dwars op de wind weg te gaan, kom je het snelst uit de gaswolk."],
  ["nood", "Een collega krijgt een bijtende vloeistof in zijn oog. Hoe lang spoel je minimaal?", ["15 minuten", "1 minuut", "5 minuten"], "Spoel minimaal 15 minuten met lauw water, ook onderweg naar de arts. Bijtende stoffen blijven anders inwerken."],
  ["nood", "Hoe lang koel je een brandwond met zacht stromend lauw water?", ["Minimaal 10 minuten", "Ongeveer 1 minuut", "Minimaal een uur"], "Door 10 minuten te koelen, stop je het doorwerken van de hitte in de huid en verminder je pijn en schade."],
  ["nood", "Een collega krijgt een chemische stof over zijn kleding en huid. Wat doe je?", ["Verontreinigde kleding uittrekken en de huid langdurig spoelen met water", "De stof wegvegen met een droge doek en verder werken", "De huid insmeren met een vette crème"], "Kleding houdt de stof tegen de huid. Uittrekken en veel water gebruiken verdunt en verwijdert de stof."],
  ["nood", "Een collega ligt bewusteloos tegen een apparaat dat mogelijk nog onder spanning staat. Wat doe je eerst?", ["De spanning uitschakelen", "Het slachtoffer direct wegtrekken", "Beginnen met reanimeren"], "Raak het slachtoffer pas aan als de spanning eraf is. Anders loop je zelf ook een stroomstoot op."],
  ["nood", "De kleding van een collega vliegt in brand. Wat doe je?", ["Hem laten stoppen en over de grond laten rollen, of de vlammen doven met een blusdeken of water", "Hem laten wegrennen naar de dichtstbijzijnde kraan", "De vlammen uitslaan met je blote handen"], "Rennen wakkert het vuur aan. Door te rollen of af te dekken sluit je de zuurstof af."],
  ["nood", "Je ontdekt een beginnende brand. Wat doe je?", ["Alarm slaan en daarna, als het veilig kan, blussen met een geschikt blusmiddel", "Eerst zelf blussen en pas alarmeren als dat mislukt", "Snel de ruimte verlaten zonder iemand te waarschuwen"], "Alarmeer eerst, zodat hulp op gang komt. Een blusactie kan mislukken, en dan is kostbare tijd verloren."],
  ["nood", "Je moet vluchten door een ruimte met rook. Hoe doe je dat?", ["Laag bij de grond blijven", "Rechtop lopen en je adem inhouden", "Eerst de ramen openen om de rook weg te laten"], "Rook en hete gassen stijgen op. Dicht bij de vloer is de lucht het best en het minst heet."],
  ["nood", "Wat doe je bij brand voordat je een gesloten deur opent?", ["Met de rug van je hand voelen of de deur of klink warm is", "De deur snel wijd openzetten om goed te kunnen kijken", "Aankloppen om te horen of er nog iemand is"], "Een warme deur wijst op brand erachter. Door te openen kan het vuur met extra zuurstof naar je toe slaan."],

  // ───────── Gevaarlijke stoffen ─────────
  ["stoffen", "Hoe ziet een CLP/GHS-gevarenpictogram eruit?", ["Een ruit met een rode rand, wit vlak en zwart symbool", "Een oranje vierkant met zwart symbool", "Een gele driehoek met zwarte rand en zwart symbool"], "Sinds CLP zijn gevarenpictogrammen witte ruiten met een rode rand. Het oranje vierkant is de oude aanduiding; de gele driehoek is een waarschuwingsbord."],
  ["stoffen", "Wat betekent het CLP-pictogram van een vlam boven een cirkel?", ["Oxiderend: de stof kan brand veroorzaken of versterken", "Ontvlambaar", "Explosief"], "De vlam boven een cirkel staat voor oxiderende stoffen. Een losse vlam betekent ontvlambaar, een exploderende bom betekent explosief."],
  ["stoffen", "Welk gevaar geeft het pictogram met een menselijk silhouet met een ster op de borst aan?", ["Ernstig gezondheidsgevaar, zoals kankerverwekkend of schadelijk voor de luchtwegen", "Acute vergiftiging met mogelijk dodelijke afloop", "Irritatie van huid en ogen"], "Dit pictogram staat voor ernstige gezondheidseffecten, vaak op lange termijn, zoals CMR-stoffen. Acuut giftig is het doodshoofd, irriterend het uitroepteken."],
  ["stoffen", "Wat betekent het pictogram met het doodshoofd met gekruiste botten?", ["Acuut giftig: kleine hoeveelheden kunnen al dodelijk zijn", "Kankerverwekkend op de lange termijn", "Bijtend voor huid en metalen"], "Het doodshoofd staat voor acute giftigheid. Voor bijtend en voor langetermijneffecten bestaan aparte pictogrammen."],
  ["stoffen", "Welk signaalwoord staat onder CLP op het etiket bij de ernstigste gevaren?", ["Gevaar", "Waarschuwing", "Let op"], "CLP kent twee signaalwoorden: ‘Gevaar’ voor de ernstigere categorieën en ‘Waarschuwing’ voor de minder ernstige."],
  ["stoffen", "Wat geven P-zinnen op een etiket aan?", ["Voorzorgsmaatregelen: hoe je veilig met de stof omgaat", "De gevaren van de stof", "Het productienummer en de houdbaarheid"], "H-zinnen (hazard) beschrijven het gevaar, P-zinnen (precautionary) de voorzorgsmaatregelen."],
  ["stoffen", "Hoeveel rubrieken heeft een veiligheidsinformatieblad (VIB)?", ["16", "10", "12"], "Een VIB heeft altijd 16 vaste rubrieken, van identificatie van de stof tot overige informatie."],
  ["stoffen", "In welke rubriek van het veiligheidsinformatieblad vind je de benodigde persoonlijke beschermingsmiddelen?", ["Rubriek 8: Maatregelen ter beheersing van blootstelling/persoonlijke bescherming", "Rubriek 2: Identificatie van de gevaren", "Rubriek 14: Informatie inzake vervoer"], "Rubriek 8 beschrijft grenswaarden en beschermende maatregelen, waaronder PBM’s."],
  ["stoffen", "In welke rubriek van het veiligheidsinformatieblad staan de eerstehulpmaatregelen?", ["Rubriek 4", "Rubriek 8", "Rubriek 11"], "Rubriek 4 bevat de eerstehulpmaatregelen. Rubriek 8 gaat over blootstelling en PBM’s, rubriek 11 over toxicologische informatie."],
  ["stoffen", "Wie moet het veiligheidsinformatieblad verstrekken?", ["De leverancier van de stof", "De Nederlandse Arbeidsinspectie", "De bedrijfsarts"], "De leverancier is verplicht een actueel VIB mee te leveren. De werkgever zorgt dat het op de werkplek beschikbaar is."],
  ["stoffen", "Wat is op het werk de belangrijkste opnameweg van gevaarlijke stoffen in het lichaam?", ["Inademing", "Via de huid", "Via de mond (inslikken)"], "Via de longen komen stoffen snel en in grote hoeveelheden in het bloed. De huid en de mond zijn ook opnamewegen, maar minder belangrijk."],
  ["stoffen", "Wat is een grenswaarde van 8 uur (TGG 8 uur)?", ["De maximale gemiddelde concentratie van een stof in de ademlucht, gemeten over een werkdag van 8 uur", "De maximale tijd dat je per dag met een stof mag werken", "De concentratie waarbij een stof kan gaan branden"], "Een grenswaarde is een concentratie in de lucht. Gemiddeld over 8 uur mag de blootstelling daar niet boven komen."],
  ["stoffen", "Waarvoor dient de grenswaarde over 15 minuten?", ["Om kortdurende piekblootstellingen te beperken", "Om aan te geven hoe lang een pauze moet duren", "Om vast te leggen hoe lang je maximaal in een besloten ruimte mag werken"], "Ook als het daggemiddelde laag is, kunnen korte pieken schadelijk zijn. Die worden beperkt met de 15-minutengrenswaarde."],
  ["stoffen", "Wat is een chronisch effect van een gevaarlijke stof?", ["Schade die ontstaat na langdurige of herhaalde blootstelling, vaak pas na jaren", "Een effect dat direct na één korte blootstelling optreedt", "Een effect dat alleen het milieu treft"], "Acute effecten treden direct op, chronische effecten ontstaan langzaam door herhaalde blootstelling, bijvoorbeeld kanker of hersenschade."],
  ["stoffen", "Waar staat CMR voor?", ["Carcinogeen, mutageen, reprotoxisch", "Corrosief, milieugevaarlijk, radioactief", "Chemisch, medisch, reactief"], "CMR-stoffen zijn kankerverwekkend, veranderen het erfelijk materiaal of zijn schadelijk voor de voortplanting."],
  ["stoffen", "Wat moet een werkgever als eerste doen als er met een kankerverwekkende stof wordt gewerkt?", ["Onderzoeken of de stof kan worden vervangen door een minder schadelijke stof of werkwijze", "Stofmaskers verstrekken", "Werknemers een gevarentoeslag betalen"], "Voor kankerverwekkende stoffen geldt een vervangingsplicht als dat technisch mogelijk is. Dat is bronaanpak."],
  ["stoffen", "Hoe sla je gevaarlijke stoffen op?", ["Gescheiden van stoffen waarmee ze gevaarlijk kunnen reageren, in de originele, geëtiketteerde verpakking", "Allemaal bij elkaar, zodat je snel ziet wat er is", "Overgeschonken in kleinere drinkflessen, zodat je makkelijk kunt doseren"], "Onverenigbare stoffen kunnen samen brand of giftige gassen veroorzaken. Zonder origineel etiket weet niemand meer wat erin zit."],
  ["stoffen", "Waarom mogen oxiderende stoffen niet bij brandbare stoffen worden opgeslagen?", ["Oxiderende stoffen kunnen een brand veroorzaken of sterk versterken", "Oxiderende stoffen verliezen dan hun werking", "Brandbare stoffen verdampen dan sneller"], "Oxiderende stoffen leveren zuurstof. Samen met brandbare stoffen ontstaat een groot brandgevaar."],
  ["stoffen", "Welke eigenschap maakt waterstofsulfide (H₂S) extra verraderlijk?", ["Bij hogere concentraties verdooft het je reukvermogen, zodat je het niet meer ruikt", "Het is lichter dan lucht en verdwijnt daardoor altijd snel", "Het is alleen gevaarlijk als het brandt"], "H₂S ruikt naar rotte eieren, maar bij gevaarlijke concentraties ruik je niets meer. Vertrouw daarom op een gasmeter."],
  ["stoffen", "Waar hoopt waterstofsulfide (H₂S) zich bij voorkeur op?", ["Op lage plekken, zoals putten en kelders, omdat het zwaarder is dan lucht", "Tegen het plafond, omdat het lichter is dan lucht", "Nergens, het mengt zich direct gelijkmatig met lucht"], "H₂S is zwaarder dan lucht en kan zich ophopen in putten, riolen en andere lage ruimtes."],
  ["stoffen", "Bij sloopwerk vind je plaatmateriaal waarvan je vermoedt dat het asbest bevat. Wat doe je?", ["Het werk stoppen, het gebied afzetten en het melden", "Het materiaal voorzichtig breken en in een afvalzak doen", "Doorwerken met een stofmasker op"], "Asbest mag alleen door gecertificeerde bedrijven worden verwijderd. Door te breken komen juist gevaarlijke vezels vrij."],
  ["stoffen", "Wat is het grootste gezondheidsgevaar van asbest?", ["Het inademen van vezels, wat na vele jaren kan leiden tot longkanker of mesothelioom", "Asbest ontbrandt al bij lage temperaturen", "Het veroorzaakt huiduitslag bij aanraking"], "Ingeademde asbestvezels blijven in de longen achter. Ziekten zoals mesothelioom ontstaan pas tientallen jaren later."],
  ["stoffen", "Welke schouderkleur heeft een gasfles met een brandbaar gas?", ["Rood", "Geel", "Heldergroen"], "Volgens EN 1089-3 betekent een rode schouder brandbaar. Geel is giftig en/of bijtend, heldergroen is inert."],
  ["stoffen", "Een gasfles heeft een lichtblauwe schouder. Wat voor gas zit erin?", ["Een oxiderend gas", "Een inert gas", "Een giftig gas"], "Lichtblauw staat voor oxiderend (brandbevorderend). Zuurstof zelf heeft een eigen kleur: wit."],
  ["stoffen", "Welke schouderkleur heeft een zuurstoffles?", ["Wit", "Lichtblauw", "Rood"], "Zuurstof heeft volgens EN 1089-3 een eigen, witte schouder. Lichtblauw is de algemene kleur voor andere oxiderende gassen."],
  ["stoffen", "Welke schouderkleur heeft een acetyleenfles?", ["Kastanjebruin", "Rood", "Wit"], "Acetyleen heeft een eigen kleur: kastanjebruin. Rood is de algemene kleur voor andere brandbare gassen, wit is zuurstof."],
  ["stoffen", "Wat betekent een gele schouder op een gasfles?", ["Giftig en/of bijtend gas", "Brandbaar gas", "Inert gas"], "Volgens EN 1089-3 staat geel voor giftig en/of bijtend."],
  ["stoffen", "Een gasfles heeft een heldergroene schouder. Wat is het belangrijkste gevaar van dit gas?", ["Verstikking doordat het gas de zuurstof verdringt", "Brand, omdat het gas brandbaar is", "Vergiftiging, omdat het gas giftig is"], "Heldergroen staat voor inert: niet brandbaar en niet giftig. In een afgesloten ruimte kan het wel de zuurstof verdringen."],
  ["stoffen", "Welk deel van de gasfles geeft volgens EN 1089-3 met een kleur het gevaar van het gas aan?", ["De schouder (de bovenkant van de fles)", "De romp van de fles", "De beschermkap van het ventiel"], "De kleurcodering zit op de schouder. De kleur van de romp is niet bepalend; lees daarnaast altijd het etiket."],
  ["stoffen", "Hoe moeten gasflessen worden opgeslagen?", ["Rechtop, vastgezet tegen omvallen en met de beschermkap op het ventiel", "Liggend op de grond, zodat ze niet kunnen omvallen", "Dicht bij een warmtebron, zodat de druk op peil blijft"], "Een omvallende fles kan het ventiel afbreken. Warmte verhoogt de druk en kan de fles laten bezwijken."],

  // ───────── Brand & explosie ─────────
  ["brand", "Welke drie elementen zijn nodig voor brand (branddriehoek)?", ["Brandbare stof, zuurstof en ontstekingstemperatuur", "Brandbare stof, wind en vocht", "Zuurstof, stikstof en rook"], "Zonder brandbare stof, zuurstof of voldoende warmte (ontstekingstemperatuur) kan er geen brand ontstaan."],
  ["brand", "Welke twee elementen voegt de brandvijfhoek toe aan de branddriehoek?", ["De juiste mengverhouding en een katalysator", "Wind en vochtigheid", "Rook en hitte"], "Naast brandstof, zuurstof en ontstekingstemperatuur moeten ook de mengverhouding kloppen en kan een katalysator de reactie mogelijk maken."],
  ["brand", "Waarop berust blussen?", ["Het wegnemen van een of meer elementen van de branddriehoek", "Het toevoegen van extra zuurstof", "Het verhogen van de temperatuur"], "Door af te koelen, de zuurstof af te sluiten of de brandstof weg te nemen, dooft het vuur."],
  ["brand", "Wat is het vlampunt van een vloeistof?", ["De laagste temperatuur waarbij de vloeistof zoveel damp vormt dat deze met een ontstekingsbron kan ontbranden", "De temperatuur waarbij de vloeistof vanzelf, zonder ontstekingsbron, gaat branden", "De temperatuur waarbij de vloeistof kookt"], "Boven het vlampunt vormt de vloeistof genoeg damp om met een vonk of vlam te ontbranden."],
  ["brand", "Benzine heeft een vlampunt ver onder 0 °C. Wat betekent dit in de praktijk?", ["Bij normale temperaturen vormt benzine altijd ontvlambare damp", "Benzine kan alleen bij vorst branden", "Benzine is bij kamertemperatuur niet brandbaar"], "Omdat de omgevingstemperatuur bijna altijd boven het vlampunt ligt, is er rond benzine vrijwel altijd ontvlambare damp."],
  ["brand", "Wat is de zelfontbrandingstemperatuur?", ["De temperatuur waarbij een stof zonder vonk of vlam vanzelf gaat branden", "De laagste temperatuur waarbij een vloeistof ontvlambare damp vormt", "De hoogste temperatuur die een brand bereikt"], "Bij de zelfontbrandingstemperatuur is geen ontstekingsbron meer nodig; een heet oppervlak is al genoeg."],
  ["brand", "Wat is de onderste explosiegrens (OEG)?", ["De laagste concentratie brandbaar gas of damp in lucht waarbij een explosie mogelijk is", "De hoogste concentratie brandbaar gas in lucht waarbij nog een explosie mogelijk is", "De laagste temperatuur waarbij een gas ontploft"], "Onder de OEG is het mengsel te arm om te ontbranden. Tussen OEG en BEG ligt het explosiegebied."],
  ["brand", "Een mengsel van gas en lucht ligt boven de bovenste explosiegrens (BEG). Wat is juist?", ["Het mengsel is te rijk om te exploderen, maar kan bij verdunning met lucht alsnog explosief worden", "Het mengsel is volledig veilig", "Het mengsel explodeert dan het hevigst"], "Boven de BEG is er te weinig zuurstof. Komt er lucht bij, dan zakt de concentratie en kom je in het explosiegebied."],
  ["brand", "Hoe voorkom je ontsteking door statische elektriciteit bij het overpompen van brandbare vloeistoffen?", ["Vaten en leidingen aarden en onderling verbinden", "In plaats van pompen overschenken met een kunststof emmer", "Een CO₂-blusser klaarzetten"], "Door te aarden en te verbinden kan statische lading wegvloeien, zodat er geen vonk ontstaat. Kunststof emmers kunnen juist lading opbouwen."],
  ["brand", "Welke van deze kan een brandbaar gasmengsel ontsteken?", ["Een heet oppervlak, zoals de uitlaat van een motor", "Een geaarde metalen leiding", "Een lekbak onder een vat"], "Ontstekingsbronnen zijn onder meer open vuur, vonken, statische ontlading en hete oppervlakken."],
  ["brand", "Tot welke brandklasse behoort brand in hout, papier en textiel?", ["A", "B", "F"], "Klasse A: vaste stoffen. B: vloeistoffen. C: gassen. D: metalen. F: vetten en oliën in keukenapparatuur."],
  ["brand", "Tot welke brandklasse behoort brand in benzine of andere brandbare vloeistoffen?", ["B", "A", "C"], "Brandbare vloeistoffen (en vaste stoffen die vloeibaar worden) vallen in klasse B."],
  ["brand", "Waar gaat brandklasse C over?", ["Gassen", "Metalen", "Frituurvet"], "Klasse C is brand in gassen, zoals propaan of aardgas."],
  ["brand", "Welke brandklasse geldt voor brand in metalen zoals magnesium of natrium?", ["D", "C", "B"], "Metaalbranden zijn klasse D en vragen een speciaal blusmiddel. Elektrische brand is geen aparte brandklasse."],
  ["brand", "Welke brandklasse geldt voor brand in frituurvet of spijsolie?", ["F", "B", "D"], "Klasse F is brand in vetten en oliën in keukenapparatuur. Blus met een F-blusser of blusdeken, nooit met water."],
  ["brand", "Waarom mag je een frituurvetbrand nooit met water blussen?", ["Het water verdampt explosief en slingert brandend vet in het rond", "Water maakt het vet giftig", "Het vet wordt door het water juist stroperig en brandt dan langer"], "Water zakt onder het hete vet, verdampt in een flits en neemt brandend vet mee: een steekvlam."],
  ["brand", "Welk blusmiddel is het meest geschikt voor een brand in een schakelkast?", ["CO₂", "Water", "Schuim"], "CO₂ geleidt geen stroom en laat geen resten achter. Water en schuim geleiden stroom."],
  ["brand", "Waar moet je op letten als je een CO₂-blusser in een kleine ruimte gebruikt?", ["CO₂ verdringt de zuurstof: verlaat de ruimte na het blussen", "CO₂ is brandbaar in een kleine ruimte", "CO₂ laat een giftig poeder achter"], "CO₂ dooft door de zuurstof te verdringen. In een kleine ruimte kan dat ook voor jou tot verstikking leiden."],
  ["brand", "Een lekkende gasleiding staat in brand. Wat doe je eerst?", ["De gastoevoer afsluiten", "Het vuur zo snel mogelijk blussen met poeder", "Water op de vlam spuiten"], "Als je een gasbrand blust terwijl het gas blijft stromen, ontstaat een explosief gasmengsel. Sluit daarom eerst de toevoer af."],
  ["brand", "Hoe blus je buiten een brand met een draagbaar blustoestel?", ["Met de wind in de rug, gericht op de basis van de vlammen", "Tegen de wind in, gericht op de top van de vlammen", "Van zo dichtbij mogelijk, gericht op de rook"], "Met de wind in de rug blijven rook en hitte bij je weg. Het blusmiddel moet op de vuurhaard komen, niet in de vlammen."],
  ["brand", "Wat betekent Ex-zone 0?", ["Een gebied waar een explosieve gasatmosfeer continu, langdurig of vaak aanwezig is", "Een gebied zonder explosiegevaar", "Een gebied waar alleen bij een storing kortdurend een explosieve atmosfeer kan ontstaan"], "Zone 0 heeft het hoogste gevaar. Zone 1: bij normaal bedrijf af en toe. Zone 2: normaal niet, en als het voorkomt dan kort."],
  ["brand", "Welke zone-indeling geldt voor gebieden met explosiegevaar door brandbaar stof?", ["Zone 20, 21 en 22", "Zone 0, 1 en 2", "Zone A, B en C"], "Voor gassen en dampen gelden zone 0, 1 en 2, voor brandbaar stof zone 20, 21 en 22."],
  ["brand", "Welke apparatuur mag je in een Ex-zone gebruiken?", ["Alleen explosieveilige apparatuur die geschikt is voor die zone", "Elk apparaat met een CE-markering", "Alle accu-apparatuur, omdat die geen snoer heeft"], "Gewone apparatuur, ook op accu, kan vonken of hete oppervlakken geven. In een Ex-zone moet de apparatuur daarvoor gecertificeerd zijn."],
  ["brand", "Waarom kan een stofexplosie uitgroeien tot een zware tweede explosie?", ["De eerste explosie doet neergeslagen stof opwervelen, dat daarna ook ontbrandt", "Stof bevat altijd giftige gassen die later ontploffen", "Stof kan pas bij de tweede ontsteking branden"], "De drukgolf van een kleine eerste explosie wervelt stof op van vloeren en balken. Die grote stofwolk ontbrandt daarna met veel meer kracht."],
  ["brand", "Welke maatregel verkleint het risico op een stofexplosie het meest?", ["Stofophoping voorkomen door afzuigen en regelmatig schoonmaken", "Het stof met perslucht wegblazen", "De ruimte warm houden zodat het stof droog blijft"], "Zonder opgehoopt stof geen stofwolk. Wegblazen met perslucht maakt juist een explosieve wolk."],

  // ───────── Elektriciteit ─────────
  ["elektra", "Welke factoren bepalen vooral de ernst van een elektrisch ongeval?", ["De stroomsterkte, de weg door het lichaam en de duur", "De kleur van de kabel en het merk van het apparaat", "De lengte van de kabel en het gewicht van het apparaat"], "Hoe groter de stroom, hoe langer hij loopt en hoe meer hij langs vitale organen zoals het hart gaat, hoe ernstiger het letsel."],
  ["elektra", "Wat is een levensgevaarlijk gevolg van stroom door het lichaam?", ["Hartkamerfibrilleren", "Gehoorschade", "Onderkoeling"], "Bij hartkamerfibrilleren trilt het hart ongecoördineerd en pompt het geen bloed meer rond. Zonder hulp is dat dodelijk."],
  ["elektra", "Waarom kan iemand een onder spanning staand voorwerp soms niet meer loslaten?", ["Door de stroom verkrampen de spieren", "Door de hitte smelt de huid vast", "Het voorwerp wordt magnetisch en trekt de hand aan"], "Stroom laat spieren samentrekken. De hand knijpt dan onwillekeurig dicht om het voorwerp."],
  ["elektra", "Bij welke lekstroom schakelt een aardlekschakelaar voor persoonsbescherming uit?", ["30 mA", "300 mA", "3 A"], "Een aardlekschakelaar van 30 mA schakelt snel uit bij een lekstroom, voordat die dodelijk kan worden."],
  ["elektra", "Hoe werkt een aardlekschakelaar?", ["Hij vergelijkt de heengaande en teruggaande stroom en schakelt uit bij een verschil", "Hij schakelt uit als de spanning te hoog wordt", "Hij schakelt uit als een apparaat meer stroom verbruikt dan toegestaan"], "Een verschil betekent dat er stroom weglekt, bijvoorbeeld via een persoon naar aarde. Uitschakelen bij overbelasting doet de installatieautomaat."],
  ["elektra", "In welke situatie beschermt een aardlekschakelaar NIET?", ["Als je tegelijk fase en nul aanraakt, terwijl je geïsoleerd van de aarde staat", "Als er via je lichaam stroom naar de aarde lekt", "Als een apparaat met randaarde een isolatiefout heeft"], "Bij contact tussen fase en nul gaat er evenveel stroom heen als terug. De aardlekschakelaar ziet dan geen verschil."],
  ["elektra", "Wat betekent het symbool van twee vierkantjes in elkaar op een elektrisch apparaat?", ["Dubbel geïsoleerd (klasse II): randaarde is niet nodig", "Het apparaat is waterdicht", "Het apparaat mag alleen op 400 V worden aangesloten"], "Bij klasse II-apparaten beschermt een extra isolatielaag tegen aanraken van spanning. Daarom hebben ze geen randaarde."],
  ["elektra", "Wat is de functie van de randaarde bij een klasse I-apparaat?", ["Bij een isolatiefout de lekstroom via de aarde afvoeren, zodat de beveiliging uitschakelt", "Het apparaat stiller laten draaien", "De spanning verlagen naar een veilige waarde"], "Komt een metalen behuizing onder spanning, dan loopt de stroom via de randaarde weg in plaats van via jou, en schakelt de beveiliging af."],
  ["elektra", "Wat is de maximale veilige wisselspanning?", ["50 V", "110 V", "230 V"], "Wisselspanning tot 50 V (en gelijkspanning tot 120 V) geldt als veilige spanning."],
  ["elektra", "Je gebruikt een veiligheidstransformator voor werk in een ketel. Waar plaats je de transformator?", ["Buiten de ketel", "In de ketel, dicht bij het werk", "Maakt niet uit, zolang hij droog staat"], "Op de transformator staat aan de ingang de volle netspanning. Die hoort niet in een besloten, geleidende ruimte."],
  ["elektra", "Waarom moet je een kabelhaspel volledig afrollen voordat je hem gebruikt?", ["Een opgerolde kabel kan te warm worden, waardoor de isolatie smelt", "Anders komt de stroom niet goed door", "Anders werkt de aardlekschakelaar niet"], "In een opgerolde kabel kan de warmte niet weg. Bij hoge belasting kan de isolatie smelten en ontstaat kortsluit- of brandgevaar."],
  ["elektra", "Je ziet dat de isolatie van een verlengkabel beschadigd is. Wat doe je?", ["De kabel niet meer gebruiken en melden", "De beschadiging omwikkelen met isolatietape en verder werken", "De kabel gebruiken zolang er geen koper zichtbaar is"], "Een beschadigde kabel moet uit gebruik en door een deskundige worden gerepareerd of vervangen. Tape is geen deugdelijke reparatie."],
  ["elektra", "Wie mag werkzaamheden aan een elektrische installatie uitvoeren?", ["Alleen personen die daarvoor zijn opgeleid en aangewezen, volgens NEN 3140", "Iedere medewerker met een VCA-diploma", "Iedereen, zolang de aardlekschakelaar werkt"], "NEN 3140 eist dat werk aan installaties wordt gedaan door vakbekwame of voldoende onderrichte personen die daarvoor zijn aangewezen."],
  ["elektra", "Wat is de eerste van de vijf veiligheidsregels voor spanningsloos werken?", ["Vrijschakelen", "Aarden en kortsluiten", "Spanningsloosheid controleren"], "De volgorde is: vrijschakelen, beveiligen tegen herinschakelen, spanningsloosheid controleren, aarden en kortsluiten, afschermen van nabije delen onder spanning."],
  ["elektra", "Welke stap volgt bij de vijf veiligheidsregels direct na het beveiligen tegen herinschakelen?", ["Controleren of de installatie spanningsloos is", "Aarden en kortsluiten", "Afschermen van nabijgelegen delen onder spanning"], "Eerst controleren dat er echt geen spanning meer is; pas daarna aarden en kortsluiten en afschermen."],
  ["elektra", "Waarom moet je bij hoogspanningslijnen afstand houden, ook als je de draad niet aanraakt?", ["Omdat de spanning kan overslaan als je te dichtbij komt", "Omdat de lijnen metaal magnetisch aantrekken", "Omdat de lijnen bij wind kunnen breken"], "Bij hoogspanning kan een vlamboog ontstaan over een afstand door de lucht. Aanraken is dus niet nodig om geraakt te worden."],
  ["elektra", "De giek van een kraan raakt een hoogspanningslijn. Wat moet de machinist doen?", ["In de cabine blijven tot de spanning is afgeschakeld, tenzij er brand is", "Direct uitstappen en wegrennen", "Uitstappen en de kraan vasthouden om hem stabiel te houden"], "In de cabine is de machinist veilig. Bij uitstappen kan hij onder spanning komen doordat hij tegelijk kraan en grond raakt."],
  ["elektra", "Een machinist moet door brand toch de cabine verlaten van een voertuig dat een hoogspanningslijn raakt. Hoe doet hij dat?", ["Met gesloten voeten wegspringen zonder voertuig en grond tegelijk te raken, en met kleine sprongetjes weggaan", "Rustig via de trap uitstappen en het voertuig vasthouden", "Met grote passen zo snel mogelijk wegrennen"], "Rond het voertuig staat spanning op de grond (stapspanning). Grote passen overbruggen een groot spanningsverschil; met gesloten voeten niet."],

  // ───────── Gereedschap & machines ─────────
  ["gereedschap", "Een collega gebruikt een schroevendraaier als breekijzer. Wat is het probleem?", ["Gereedschap dat wordt gebruikt waarvoor het niet bedoeld is, kan breken of wegschieten en letsel veroorzaken", "Er is geen probleem zolang de schroevendraaier geïsoleerd is", "Alleen de schroevendraaier kan beschadigen"], "Gebruik gereedschap alleen waarvoor het bedoeld is. Verkeerd gebruik is een bekende oorzaak van ongevallen."],
  ["gereedschap", "Een medewerker haalt de beschermkap van een haakse slijper, omdat hij dan beter kan zien. Wat doe je?", ["Hem laten stoppen en de beschermkap laten terugplaatsen", "Toestaan als hij een veiligheidsbril draagt", "Toestaan voor korte klussen"], "De beschermkap vangt vonken en brokstukken op als een schijf breekt. Een veiligheidsbril beschermt alleen de ogen."],
  ["gereedschap", "Waar let je op bij het monteren van een slijpschijf?", ["Het maximale toerental van de schijf moet minstens gelijk zijn aan het toerental van de machine", "De schijf mag een lager maximumtoerental hebben dan de machine als je voorzichtig werkt", "De schijf moet zo groot mogelijk zijn, ook als de beschermkap dan niet meer past"], "Draait de machine sneller dan de schijf aankan, dan kan de schijf uit elkaar spatten."],
  ["gereedschap", "Waarom draag je geen handschoenen bij het werken aan een kolomboormachine?", ["De handschoen kan worden gegrepen door de draaiende boor, waardoor je hand wordt meegetrokken", "Handschoenen zijn niet bestand tegen boorolie", "Je voelt dan niet meer of de boor bot wordt"], "Draaiende delen kunnen stof grijpen. Om dezelfde reden draag je geen loshangende kleding, sieraden of los lang haar."],
  ["gereedschap", "Welke maatregel hoort bij het werken aan een draaibank?", ["Geen loshangende kleding, sieraden of los lang haar", "Werkhandschoenen dragen voor een betere grip", "Het werkstuk met de hand tegenhouden als het gaat trillen"], "Draaiende delen kunnen kleding, sieraden of haar grijpen en je lichaam meetrekken."],
  ["gereedschap", "Een collega blaast met perslucht stof van zijn kleding. Waarom is dit gevaarlijk?", ["Perslucht kan via de huid of lichaamsopeningen het lichaam binnendringen en ernstig letsel veroorzaken", "Het stof blijft daardoor juist in de kleding zitten", "Perslucht is alleen gevaarlijk boven 10 bar"], "Perslucht kan in de bloedbaan of lichaamsholten terechtkomen en zelfs dodelijk zijn. Richt perslucht nooit op jezelf of een ander."],
  ["gereedschap", "Wat betekent een CE-markering op een machine?", ["De fabrikant verklaart dat de machine voldoet aan de Europese veiligheidseisen", "De machine is goedgekeurd door de Nederlandse Arbeidsinspectie", "De machine is in Europa gemaakt"], "Met de CE-markering geeft de fabrikant aan dat het product voldoet aan de Europese richtlijnen, zoals de Machinerichtlijn."],
  ["gereedschap", "Hoe ziet een noodstop er meestal uit?", ["Een rode paddenstoelknop op een gele ondergrond", "Een groene drukknop op een witte ondergrond", "Een zwarte tuimelschakelaar"], "De noodstop valt op door zijn kleuren en vorm, zodat je hem in een noodsituatie direct kunt vinden."],
  ["gereedschap", "Na een noodstop is de oorzaak verholpen. Wat geldt voor het opnieuw starten van de machine?", ["De noodstop moet worden ontgrendeld en daarna moet de machine bewust opnieuw worden gestart", "De machine start vanzelf zodra de noodstop wordt ontgrendeld", "De machine mag pas weer aan na een keuring door de Arbeidsinspectie"], "Een machine mag na het ontgrendelen van de noodstop niet vanzelf starten. Iemand moet haar bewust opnieuw aanzetten."],
  ["gereedschap", "Hoe verhelp je een storing aan een machine veilig?", ["Machine uitschakelen, vergrendelen tegen inschakelen en controleren dat hij niet kan starten", "De machine op de laagste snelheid laten draaien", "Een collega bij de schakelaar laten staan"], "Een collega kan worden afgeleid of vergissen. Alleen een vergrendeling met eigen slot voorkomt betrouwbaar dat de machine start."],
  ["gereedschap", "Wie mag een heftruck besturen?", ["Alleen een medewerker die daarvoor is opgeleid en door de werkgever is aangewezen", "Iedereen met een autorijbewijs", "Iedere medewerker vanaf 16 jaar"], "Een heftruck vraagt specifieke kennis en vaardigheden. De werkgever moet zorgen dat alleen deskundige, aangewezen bestuurders ermee rijden."],
  ["gereedschap", "Een collega wil op de vork van een heftruck omhoog om iets uit een stelling te pakken. Wat doe je?", ["Het verbieden", "Het toestaan als de chauffeur heel langzaam heft", "Het toestaan als de collega een helm draagt"], "Personen mogen alleen worden geheven in een daarvoor goedgekeurde werkbak of met een geschikt hoogwerker."],
  ["gereedschap", "De kop van een beitel is uitgeslagen tot een ‘paddenstoel’ met bramen. Wat doe je?", ["De bramen laten wegslijpen of de beitel vervangen", "Gewoon gebruiken, dat hoort bij een oude beitel", "Juist harder slaan, zodat de bramen afbreken"], "Bramen kunnen bij een hamerslag afspringen en als scherpe splinters ogen of huid raken."],
  ["gereedschap", "Waarom wordt elektrisch handgereedschap periodiek gekeurd?", ["Om defecten, zoals beschadigde isolatie, tijdig op te sporen", "Om het gereedschap sneller te laten werken", "Omdat de garantie anders vervalt"], "Slijtage en beschadigingen zie je niet altijd. Een periodieke keuring voorkomt dat defect gereedschap onder spanning komt te staan."],

  // ───────── Werken op hoogte ─────────
  ["hoogte", "Vanaf welke valhoogte zijn maatregelen tegen vallen in ieder geval verplicht?", ["2,5 meter", "1 meter", "4 meter"], "Vanaf 2,5 meter is er altijd valgevaar in de zin van het Arbobesluit. Bij bijzondere gevaren gelden maatregelen al lager."],
  ["hoogte", "Je werkt op 1,5 meter hoogte boven uitstekende wapeningsstaven. Zijn valmaatregelen nodig?", ["Ja, bij bijzondere gevaren zijn maatregelen ongeacht de hoogte nodig", "Nee, pas vanaf 2,5 meter", "Nee, alleen als de opdrachtgever erom vraagt"], "Bij vallen in water, op scherpe of gevaarlijke voorwerpen of in machines moeten valmaatregelen ongeacht de hoogte worden genomen."],
  ["hoogte", "Welke valbeveiliging heeft de voorkeur?", ["Een collectieve voorziening, zoals een leuning of steiger", "Een harnasgordel met valdemper", "Een rood-wit lint langs de rand"], "Collectieve voorzieningen beschermen iedereen en werken zonder dat de werknemer er iets voor hoeft te doen. PBM zijn het laatste redmiddel."],
  ["hoogte", "Aan welke maten voldoet een randbeveiliging?", ["Bovenregel op 1 m, tussenregel op 0,5 m en een kantplank van minimaal 15 cm", "Bovenregel op 0,8 m, geen tussenregel en een kantplank van 5 cm", "Bovenregel op 1,5 m en een tussenregel op 1 m"], "Leuning 1 m, knie- of tussenregel 0,5 m en kantplank minimaal 15 cm: zo val je er niet overheen of onderdoor en valt er niets af."],
  ["hoogte", "Wat is het doel van een kantplank?", ["Voorkomen dat voorwerpen van de werkvloer naar beneden vallen", "Het steigerdek extra stevig maken", "Een plek bieden om de steigerkaart aan te hangen"], "De kantplank houdt gereedschap en materiaal op het werkvlak en voorkomt dat je voet van de rand schuift."],
  ["hoogte", "Onder welke hoek zet je een ladder op?", ["Tussen 65° en 75°", "Tussen 45° en 55°", "Zo steil mogelijk, bijna 90°"], "Bij een te vlakke hoek glijdt de voet weg, bij een te steile hoek kan de ladder achterover vallen."],
  ["hoogte", "Hoe ver moet een ladder die als toegang dient boven de uitstapplaats uitsteken?", ["1 meter", "30 centimeter", "2 meter"], "Door de ladder 1 meter te laten uitsteken, heb je houvast bij het op- en afstappen."],
  ["hoogte", "Wat houdt driepuntscontact op een ladder in?", ["Altijd twee handen en een voet, of twee voeten en een hand op de ladder", "Drie personen houden de ladder vast", "De ladder rust op drie steunpunten"], "Met drie contactpunten houd je altijd grip. Daarom klim je niet met materiaal in je handen."],
  ["hoogte", "Wanneer mag een ladder als werkplek worden gebruikt?", ["Alleen voor kortdurend, licht werk met een beperkt risico", "Voor alle werkzaamheden tot 10 meter hoogte", "Voor elk werk, als er geen steiger op de bouwplaats aanwezig is"], "Een ladder is in de eerste plaats een toegangsmiddel. Voor langer of zwaarder werk gebruik je een steiger of hoogwerker."],
  ["hoogte", "Op een steiger hangt een rode steigerkaart. Wat betekent dit?", ["De steiger mag niet worden gebruikt", "De steiger is goedgekeurd voor zware belasting", "Alleen de leidinggevende mag de steiger betreden"], "Groen betekent goedgekeurd en vrijgegeven voor gebruik. Rood betekent: niet betreden, de steiger is (nog) niet veilig."],
  ["hoogte", "Een leuning van de steiger zit in de weg bij je werk. Wat doe je?", ["De steigerbouwer laten komen om de steiger aan te passen", "De leuning tijdelijk weghalen en na afloop terugplaatsen", "De leuning weghalen en in plaats daarvan een harnasgordel dragen"], "Alleen een deskundige steigerbouwer mag een steiger wijzigen. Daarna moet de steiger opnieuw worden gekeurd."],
  ["hoogte", "Mag je een rolsteiger verplaatsen terwijl er iemand op staat?", ["Nee, nooit met personen of losse materialen erop", "Ja, als het langzaam gebeurt", "Ja, als de persoon zich goed vasthoudt"], "Tijdens het verrijden kan de rolsteiger kantelen of een wiel in een gat rijden. Iedereen en alles moet er eerst af."],
  ["hoogte", "Wat controleer je voordat je een rolsteiger beklimt?", ["Dat de wielen op de rem staan en de stabilisatoren zijn geplaatst", "Dat de wielen vrij kunnen draaien, zodat de steiger kan meegeven", "Alleen of het werkplatform schoon is"], "Wielen op de rem en stabilisatoren voorkomen dat de rolsteiger wegrolt of kantelt."],
  ["hoogte", "Waar bevestig je bij voorkeur de vanglijn van je harnasgordel?", ["Aan een goedgekeurd ankerpunt boven je", "Aan een ankerpunt ter hoogte van je voeten", "Aan een willekeurige leiding in de buurt"], "Een ankerpunt boven je beperkt de valafstand en de klap. Het ankerpunt moet sterk genoeg zijn om een val op te vangen."],
  ["hoogte", "Wat is hangtrauma?", ["Een levensbedreigende toestand doordat bloed zich in de benen ophoopt als je na een val stil in je harnas hangt", "Schouderletsel door een te strak afgestelde gordel", "Hoogtevrees die ontstaat na een val"], "Door stil te hangen stagneert de bloedsomloop. Iemand kan binnen korte tijd bewusteloos raken."],
  ["hoogte", "Wat betekent het risico op hangtrauma voor werken met een harnasgordel?", ["Er moet vooraf een reddingsplan zijn om iemand snel te bevrijden", "Je mag een harnasgordel nooit langer dan een uur dragen", "Je moet het harnas los dragen zodat het niet knelt"], "Na een val moet het slachtoffer zo snel mogelijk worden gered. Dat moet vóór aanvang van het werk geregeld zijn."],
  ["hoogte", "Een harnasgordel met valdemper heeft een val opgevangen. Wat doe je ermee?", ["Afkeuren en uit gebruik nemen", "Controleren op zichtbare schade en daarna opnieuw gebruiken", "Alleen de vanglijn vervangen"], "Na een val kunnen banden en naden onzichtbaar beschadigd zijn en is de valdemper gebruikt. Het geheel moet uit gebruik."],
  ["hoogte", "Welke maatregel beschermt mensen beneden het best tegen vallende voorwerpen?", ["Het gebied onder de werkzaamheden afzetten", "‘Pas op’ roepen als er iets valt", "Collega’s beneden vragen om goed omhoog te kijken"], "Door af te zetten komt niemand in de gevarenzone. Kantplanken en het vastzetten van gereedschap helpen ook."],

  // ───────── Besloten ruimten ─────────
  ["besloten", "Wat is een besloten ruimte?", ["Een ruimte met beperkte in- en uitgangen en slechte ventilatie, niet bedoeld om er continu te verblijven", "Elke ruimte met een deur die op slot kan", "Een kantoor zonder ramen"], "Voorbeelden zijn tanks, ketels, putten en kruipruimtes. Daar kan zich een gevaarlijke atmosfeer vormen."],
  ["besloten", "Hoeveel zuurstof bevat normale lucht ongeveer?", ["21%", "16%", "78%"], "Lucht bestaat voor ongeveer 21% uit zuurstof en voor 78% uit stikstof."],
  ["besloten", "Waarom is zuurstoftekort zo gevaarlijk?", ["Je merkt het niet op tijd en kunt plotseling bewusteloos raken", "Het geeft altijd eerst een hevige hoestprikkel", "Het is alleen gevaarlijk bij zwaar lichamelijk werk"], "Zuurstoftekort ruik en zie je niet. Je beoordelingsvermogen neemt af, en je kunt zonder waarschuwing bewusteloos raken."],
  ["besloten", "Waarom mag je een besloten ruimte nooit ventileren met zuivere zuurstof?", ["Een teveel aan zuurstof vergroot het brandgevaar enorm", "Zuivere zuurstof verstikt omdat het zwaarder is dan lucht", "Zuivere zuurstof beschadigt de gasmeter"], "In zuurstofrijke lucht branden materialen, ook kleding, veel feller. Ventileer altijd met schone lucht."],
  ["besloten", "Waar hopen zware gassen, zoals propaan, zich op in een besloten ruimte?", ["Op de laagste punten", "Tegen het plafond", "Gelijkmatig verdeeld door de ruimte"], "Gassen die zwaarder zijn dan lucht zakken naar beneden en blijven in putten en op de bodem hangen."],
  ["besloten", "Wanneer wordt in een besloten ruimte gemeten op zuurstof en gevaarlijke gassen?", ["Voor het betreden én tijdens het werk", "Alleen voor het betreden", "Alleen als iemand klachten krijgt"], "De atmosfeer kan tijdens het werk veranderen, bijvoorbeeld door lassen of vrijkomende stoffen. Daarom ook tijdens het werk meten."],
  ["besloten", "Wie voert de gasmeting uit voordat een besloten ruimte wordt betreden?", ["Een deskundige met een gekalibreerd meetinstrument", "Iedereen die in de buurt is, op de geur", "De mangatwacht, door eerst even naar binnen te gaan"], "Gevaarlijke gassen zijn vaak niet te ruiken. Alleen een goede meting door een deskundige geeft zekerheid."],
  ["besloten", "Wat is een taak van de mangatwacht?", ["Contact houden met de mensen binnen en bij problemen alarm slaan", "Zelf naar binnen gaan zodra iemand niet reageert", "Tussendoor ander werk in de buurt doen"], "De mangatwacht blijft bij de opening, houdt contact en toezicht, en alarmeert bij problemen. Hij verlaat zijn post niet."],
  ["besloten", "Een collega in een tank wordt onwel. Wat doe je als mangatwacht?", ["Alarm slaan en zelf niet naar binnen gaan", "Direct naar binnen gaan om hem eruit te halen", "Een filtermasker opzetten en naar binnen gaan"], "Veel slachtoffers in besloten ruimten zijn hulpverleners die zelf naar binnen gingen. Redding gebeurt door opgeleide redders met onafhankelijke adembescherming."],
  ["besloten", "Waarom worden leidingen naar een besloten ruimte geblindeerd?", ["Om te voorkomen dat stoffen of stoom de ruimte in kunnen stromen", "Om de ruimte donker te maken voor laswerk", "Om de druk in de leidingen te verhogen"], "Een gesloten afsluiter kan lekken of per ongeluk open worden gezet. Een blindflens sluit de leiding betrouwbaar af."],
  ["besloten", "Welk elektrisch gereedschap gebruik je in een besloten, geleidende ruimte zoals een ketel?", ["Gereedschap op veilige spanning via een veiligheidstransformator die buiten staat", "Gewoon 230 V-gereedschap met een lange verlengkabel", "Gereedschap op 400 V, omdat dat krachtiger is"], "In een geleidende ruimte is de kans op een stroomongeval groot. Gebruik veilige spanning en houd de transformator buiten."],

  // ───────── Hijsen ─────────
  ["hijsen", "Mag je onder een hangende last doorlopen?", ["Nee, nooit", "Ja, als je een helm draagt", "Ja, als de last minder dan een ton weegt"], "Een last kan altijd vallen, bijvoorbeeld door een breuk of een losgeschoten strop. Een helm beschermt daar niet tegen."],
  ["hijsen", "Wie geeft tijdens het hijsen de aanwijzingen aan de kraanmachinist?", ["Eén aangewezen hijsbegeleider", "Iedereen die de last kan zien", "Afwisselend de ploegleden die het dichtst bij de last staan"], "Bij meerdere aanwijzers ontstaat verwarring. Daarom geeft één hijsbegeleider de signalen."],
  ["hijsen", "Wie mag tijdens het hijsen een noodstopsignaal aan de machinist geven?", ["Iedereen die gevaar ziet", "Alleen de hijsbegeleider", "Alleen de uitvoerder"], "Normale aanwijzingen komen van één hijsbegeleider, maar op een noodstop van wie dan ook moet de machinist direct reageren."],
  ["hijsen", "Wie mag een mobiele kraan bedienen?", ["Alleen een deskundige kraanmachinist met het juiste certificaat", "Iedere medewerker met een VCA-diploma", "Iedereen met een groot rijbewijs"], "Voor het bedienen van mobiele kranen is een erkend certificaat verplicht. Een rijbewijs zegt niets over hijsen."],
  ["hijsen", "Wat betekent WLL op een hijsmiddel?", ["Working Load Limit: de maximale werklast", "De breukbelasting van het hijsmiddel", "Het eigen gewicht van het hijsmiddel"], "De WLL is de maximale last waarmee je het hijsmiddel onder normale omstandigheden mag belasten. De breuklast ligt veel hoger."],
  ["hijsen", "Wat doe je voordat je een hijsband of ketting gebruikt?", ["Controleren op beschadigingen en nagaan of hij gekeurd is en een leesbaar label heeft", "Niets, de jaarlijkse keuring is voldoende", "Het label eraf halen, zodat het niet blijft haken"], "Hijsmiddelen worden periodiek gekeurd, maar schade kan ook tussendoor ontstaan. Controleer ze voor elk gebruik; zonder label: niet gebruiken."],
  ["hijsen", "Wat is de maximale tophoek tussen twee stroppen?", ["120°", "60°", "180°"], "Bij grotere tophoeken wordt de kracht in de stroppen te groot. Houd de tophoek maximaal 120°, liefst kleiner."],
  ["hijsen", "Welke kracht werkt op elke strop bij een tophoek van 120°?", ["Evenveel als het volledige gewicht van de last", "De helft van het gewicht van de last", "Een kwart van het gewicht van de last"], "Bij 120° draagt elke strop evenveel als de hele last. Bij kleinere hoeken is de belasting per strop lager."],
  ["hijsen", "Wat gebeurt er met de belasting op twee stroppen als de tophoek groter wordt?", ["De belasting per strop neemt toe", "De belasting per strop neemt af", "De belasting blijft gelijk"], "Hoe breder de stroppen uit elkaar staan, hoe meer ze zijwaarts trekken en hoe zwaarder ze worden belast."],
  ["hijsen", "Waarvoor gebruik je een stuurlijn bij het hijsen?", ["Om de last op afstand te sturen, zonder onder of vlak naast de last te staan", "Om de last te zekeren als de strop breekt", "Om de kraan aan de grond te verankeren"], "Met een stuurlijn kun je draaien en slingeren voorkomen terwijl je buiten de gevarenzone blijft."],
  ["hijsen", "Tijdens het hijsen neemt de wind sterk toe. Wat doe je?", ["Stoppen als de toegestane windsnelheid voor de kraan of de last wordt overschreden", "Doorgaan en de last sneller hijsen", "Doorgaan, want de kraan heeft een overlastbeveiliging"], "Wind op een last met een groot oppervlak kan de kraan overbelasten of de last laten zwaaien. De grenzen van de fabrikant zijn leidend."],
  ["hijsen", "Een kraan moet in de buurt van een bovengrondse hoogspanningslijn werken. Wat is juist?", ["Vooraf met de netbeheerder afspraken maken over een veilige afstand of het afschakelen van de lijn", "De kraan mag werken zolang de giek de lijn niet raakt", "De machinist moet rubberen handschoenen dragen"], "Hoogspanning kan overslaan zonder dat de giek de lijn raakt. Afstand of afschakelen moet vooraf zijn geregeld."],
  ["hijsen", "Hoe stel je een mobiele kraan op?", ["Op een draagkrachtige, vlakke ondergrond, zo nodig met stempelplaten onder de stempels", "Vlak naast de rand van een sleuf, zodat de kraan dichter bij het werk staat", "Op de wielen, zodat hij snel verplaatst kan worden"], "Zakt een stempel weg, dan kan de kraan kantelen. Een slootrand of vers aangevulde grond draagt de druk niet."],

  // ───────── Fysieke belasting & fysische factoren ─────────
  ["fysiek", "Wat is volgens de NIOSH-methode het maximale tilgewicht onder ideale omstandigheden?", ["23 kg", "18 kg", "35 kg"], "Onder ideale omstandigheden is 23 kg het maximum. Bij draaien, ver reiken of vaak tillen ligt de grens lager."],
  ["fysiek", "Wat is een goede tiltechniek?", ["Last dicht bij het lichaam, rug recht, door de knieën en niet draaien met de romp", "Benen gestrekt en vanuit de rug tillen", "Last op armlengte houden voor een beter zicht"], "Hoe verder de last van je lichaam, hoe groter de belasting op je rug. Draaien tijdens het tillen belast de tussenwervelschijven extra."],
  ["fysiek", "Wat is de beste maatregel om zwaar tillen te voorkomen?", ["Tilhulpmiddelen gebruiken, zoals een takel, vacuümheffer of pallettruck", "Een rugband dragen", "Sneller tillen, zodat de belasting korter duurt"], "Tilhulpmiddelen nemen de belasting weg. Een rugband voorkomt geen rugletsel."],
  ["fysiek", "Wat moet de werkgever doen vanaf een dagelijkse geluidsblootstelling van 80 dB(A)?", ["Gehoorbescherming beschikbaar stellen en voorlichting geven", "Het werk direct stilleggen", "Niets, pas vanaf 90 dB(A) gelden verplichtingen"], "Vanaf 80 dB(A) (onderste actiewaarde) moet gehoorbescherming beschikbaar zijn en moeten werknemers voorlichting krijgen."],
  ["fysiek", "Vanaf welke dagelijkse geluidsblootstelling is het dragen van gehoorbescherming verplicht?", ["85 dB(A)", "80 dB(A)", "95 dB(A)"], "Bij 80 dB(A) moet gehoorbescherming beschikbaar zijn; vanaf 85 dB(A) (bovenste actiewaarde) is dragen verplicht."],
  ["fysiek", "Wat betekent de grenswaarde van 87 dB(A)?", ["Deze waarde mag, rekening houdend met de gedragen gehoorbescherming, niet worden overschreden", "Vanaf deze waarde moet gehoorbescherming beschikbaar zijn", "Onder deze waarde is geluid niet schadelijk"], "87 dB(A) is de grenswaarde van wat er daadwerkelijk bij het oor aankomt, dus met de gehoorbescherming meegerekend."],
  ["fysiek", "Het geluidsniveau stijgt met 3 dB(A). Wat betekent dit?", ["De geluidsenergie verdubbelt", "Het geluid wordt 3% harder", "De geluidsenergie wordt tien keer zo groot"], "De decibelschaal is logaritmisch: elke 3 dB erbij is een verdubbeling van de geluidsenergie."],
  ["fysiek", "Bij 85 dB(A) krijg je in 8 uur een bepaalde geluidsdosis. Na hoeveel tijd krijg je bij 88 dB(A) dezelfde dosis?", ["4 uur", "7 uur", "2 uur"], "3 dB meer is een verdubbeling van de energie. Dezelfde dosis bereik je dan in de helft van de tijd."],
  ["fysiek", "Wat is juist over lawaaidoofheid?", ["Het is blijvende gehoorschade die niet te genezen is", "Het herstelt na een paar weken rust volledig", "Het ontstaat alleen door één harde knal, niet door langdurig lawaai"], "Lawaai beschadigt de haarcellen in het binnenoor. Die groeien niet terug, dus de schade is blijvend."],
  ["fysiek", "Wat kan langdurig werken met trillend handgereedschap veroorzaken?", ["Witte vingers: schade aan bloedvaten en zenuwen in de handen", "Spataderen in de benen", "Longklachten"], "Hand-armtrillingen beschadigen bloedvaten en zenuwen. De vingers worden wit en gevoelloos, vooral bij kou."],
  ["fysiek", "Een machinist rijdt de hele dag met een graafmachine over oneffen terrein. Welke klacht ligt voor de hand?", ["Rugklachten door lichaamstrillingen", "Witte vingers", "Lasogen"], "Lichaamstrillingen via stoel en vloer belasten vooral de onderrug. Witte vingers komen door hand-armtrillingen."],
  ["fysiek", "Welke maatregel helpt tegen hittestress?", ["Regelmatig water drinken en extra pauzes in de koelte", "Het zware werk juist op het heetst van de dag doen", "Weinig drinken om minder vaak naar het toilet te hoeven"], "Bij hitte verlies je veel vocht. Voldoende drinken, pauzes en zwaar werk op koelere momenten voorkomen oververhitting."],
  ["fysiek", "Welke drie principes beschermen tegen ioniserende straling?", ["Tijd, afstand en afscherming", "Gehoorbescherming, veiligheidsbril en handschoenen", "Ventileren, spoelen en afdekken"], "Beperk de blootstellingstijd, houd zoveel mogelijk afstand en gebruik afscherming zoals lood of beton."],
  ["fysiek", "Er worden röntgenopnamen van lasnaden gemaakt en het gebied is afgezet. Wat doe je?", ["Buiten de afzetting blijven tot die wordt opgeheven", "Snel doorlopen, dan is de blootstelling kort", "Doorlopen als je op grote afstand van de bron blijft"], "De afzetting geeft de veilige grens aan. Ioniserende straling zie, ruik en voel je niet."],
  ["fysiek", "Een collega kijkt zonder bescherming naar laswerk. Wat kan het gevolg zijn?", ["Lasogen: een pijnlijke ontsteking van het hoornvlies, vaak pas uren later", "Blijvende kleurenblindheid", "Geen, alleen de lasser zelf loopt risico"], "Het uv-licht van de lasboog beschadigt het hoornvlies. De pijn komt meestal pas na enkele uren. Omstanders beschermen met lasschermen."],
  ["fysiek", "Hoe raakt iemand besmet met legionella?", ["Door het inademen van waterdruppeltjes met besmet water", "Door het drinken van besmet water", "Door contact met een besmet persoon"], "Legionella verspreidt zich via vernevelend water, zoals uit douches of koeltorens. Mens-op-mensbesmetting komt niet voor."],
  ["fysiek", "Hoe kun je de ziekte van Weil oplopen?", ["Via water of grond die besmet is met urine van ratten", "Via een tekenbeet", "Via het inademen van lasrook"], "De bacterie komt via wondjes of slijmvliezen het lichaam binnen. Wie in of bij water en riolen werkt, loopt extra risico."],
  ["fysiek", "Hoe bescherm je je tegen tetanus bij werk in de grond of met roestig materiaal?", ["Vaccinatie en wondjes goed schoonmaken", "Een stofmasker dragen", "Na het werk extra water drinken"], "De tetanusbacterie leeft in grond en komt via wondjes binnen. Vaccinatie beschermt."],

  // ───────── PBM & signalering ─────────
  ["pbm", "Waarom zijn persoonlijke beschermingsmiddelen het laatste redmiddel?", ["Ze nemen het gevaar niet weg en beschermen alleen als ze goed en consequent worden gebruikt", "Omdat PBM duurder zijn dan andere maatregelen", "Omdat PBM alleen bij noodsituaties mogen worden gebruikt"], "PBM staan onderaan de arbeidshygiënische strategie. Eerst moet het gevaar zoveel mogelijk bij de bron en collectief worden aangepakt."],
  ["pbm", "Wie betaalt de voorgeschreven persoonlijke beschermingsmiddelen?", ["De werkgever", "De werknemer, die een deel terugkrijgt", "Werkgever en werknemer ieder de helft"], "De werkgever moet PBM kosteloos ter beschikking stellen. De werknemer moet ze gebruiken."],
  ["pbm", "Waaraan moet een PBM minimaal voldoen?", ["Het moet een CE-markering hebben", "Het moet van een Nederlands merk zijn", "Het moet door de werknemer zelf zijn uitgezocht"], "Met de CE-markering verklaart de fabrikant dat het PBM voldoet aan de Europese eisen."],
  ["pbm", "Welk PBM valt in categorie III (bescherming tegen dodelijk of onherstelbaar letsel)?", ["Een harnasgordel", "Een veiligheidshelm", "Tuinhandschoenen"], "Categorie III omvat onder meer valbescherming en adembescherming. Een helm valt in categorie II, eenvoudige handschoenen in categorie I."],
  ["pbm", "Wat geldt voor het gebruik van PBM uit categorie III, zoals adembescherming?", ["Gebruikers moeten een training in het juiste gebruik krijgen", "Ze mogen zonder instructie worden gebruikt", "Ze mogen alleen door de bedrijfsarts worden uitgereikt"], "Bij categorie III-PBM kan verkeerd gebruik dodelijk zijn. Training is daarom verplicht."],
  ["pbm", "Een medewerker weigert zijn verplichte veiligheidsbril te dragen, omdat die beslaat. Wat doe je?", ["Hem erop aanspreken dat dragen verplicht is en samen zoeken naar een beter passend of anti-condensmodel", "Het toestaan, want draagcomfort gaat voor", "Hem een formele waarschuwing geven zonder verder gesprek"], "Dragen is verplicht, maar een PBM moet ook passen. Door de oorzaak op te lossen wordt het PBM beter gedragen."],
  ["pbm", "Je helm krijgt een harde klap van een vallend voorwerp, maar je ziet geen schade. Wat doe je?", ["De helm vervangen", "Gewoon verder gebruiken", "De helm met tape verstevigen"], "Na een zware klap kan de helm onzichtbaar beschadigd zijn en beschermt hij minder goed. Vervang hem altijd."],
  ["pbm", "Wanneer mag je een filtermasker gebruiken?", ["Als er voldoende zuurstof is en bekend is welke stof in welke concentratie aanwezig is", "Altijd, een filtermasker beschermt tegen alle stoffen", "Juist bij zuurstoftekort, omdat het masker zuurstof toevoegt"], "Een filter reinigt alleen de omgevingslucht en voegt geen zuurstof toe. Het werkt alleen tegen de stof waarvoor het bedoeld is."],
  ["pbm", "Wanneer is onafhankelijke adembescherming, zoals een ademluchttoestel, nodig?", ["Bij zuurstoftekort of een onbekende of te hoge concentratie van een gevaarlijke stof", "Bij houtstof van zaagwerk", "Alleen bij werk in de buitenlucht"], "Onafhankelijke adembescherming voert schone lucht aan en werkt los van de omgevingslucht."],
  ["pbm", "Welke kleur heeft een A-filter tegen organische dampen, zoals van oplosmiddelen?", ["Bruin", "Grijs", "Geel"], "A = bruin (organisch), B = grijs (anorganisch), E = geel (zuur), K = groen (ammoniak), P = wit (deeltjes)."],
  ["pbm", "Welk filter gebruik je tegen anorganische gassen, zoals chloor?", ["B – grijs", "A – bruin", "K – groen"], "B-filters (grijs) zijn voor anorganische gassen, zoals chloor."],
  ["pbm", "Welk filter gebruik je tegen ammoniak?", ["K – groen", "E – geel", "P – wit"], "Het K-filter (groen) is bedoeld voor ammoniak en ammoniakderivaten."],
  ["pbm", "Welk filter beschermt tegen zure gassen, zoals zwaveldioxide?", ["E – geel", "B – grijs", "A – bruin"], "Het E-filter (geel) is bedoeld voor zure gassen, zoals zwaveldioxide."],
  ["pbm", "Welk filter beschermt tegen stof en andere deeltjes?", ["P – wit", "K – groen", "A – bruin"], "Het P-filter (wit) houdt deeltjes tegen. Tegen gassen en dampen doet het niets."],
  ["pbm", "Waarom moet je gehoorbescherming dragen zolang je in het lawaai bent?", ["Omdat al kort afzetten de bescherming over de hele dag sterk vermindert", "Omdat het anders uit je oren valt", "Omdat het anders niet meer terugpast"], "Door de logaritmische decibelschaal leveren een paar minuten zonder bescherming al een groot deel van de dagdosis op."],
  ["pbm", "Welke oogbescherming is het meest geschikt bij het overgieten van bijtende vloeistoffen?", ["Een ruimzichtbril, eventueel met een gelaatsscherm", "Een veiligheidsbril zonder zijkappen", "Een getinte zonnebril"], "Een ruimzichtbril sluit rondom af tegen spatten. Een gelaatsscherm beschermt daarnaast het gezicht."],
  ["pbm", "Hoe ziet een verbodsbord eruit?", ["Rond, met een rode rand en rode schuine balk, wit vlak en zwart symbool", "Rond, met een blauw vlak en wit symbool", "Driehoekig, met een geel vlak, zwarte rand en zwart symbool"], "Verbod: rond met rode rand en balk. Gebod: rond en blauw. Waarschuwing: gele driehoek."],
  ["pbm", "Wat betekent een rond blauw bord met een wit symbool van een helm?", ["Helm dragen verplicht", "Helm dragen verboden", "Waarschuwing voor vallende voorwerpen"], "Ronde blauwe borden zijn gebodsborden: je moet iets doen, hier een helm dragen."],
  ["pbm", "Wat voor bord is een gele driehoek met zwarte rand en zwart symbool?", ["Een waarschuwingsbord", "Een gebodsbord", "Een reddingsbord"], "Gele driehoeken waarschuwen voor een gevaar, bijvoorbeeld elektrische spanning of een heftruck."],
  ["pbm", "Wat geeft een groen rechthoekig of vierkant bord met wit symbool aan?", ["Redding of veiligheid, zoals een nooduitgang of EHBO-post", "Een brandblusmiddel", "Een verplichting"], "Groene borden wijzen de weg naar veiligheid: nooduitgangen, vluchtroutes, EHBO en verzamelplaatsen."],
  ["pbm", "Waar wijst een rood vierkant bord met wit symbool op?", ["Brandbestrijdingsmiddelen, zoals een brandblusser of brandslang", "Een verbod", "Een nooduitgang"], "Rode vierkante of rechthoekige borden geven de plaats van brandbestrijdingsmiddelen aan."]
];
